import{_ as t,o as s,c as n,a2 as i}from"./chunks/framework.Dg5D4OHa.js";const p=JSON.parse('{"title":"central command sync-environments","description":"","frontmatter":{},"headers":[],"relativePath":"commands/command-sync-environments.md","filePath":"commands/command-sync-environments.md"}'),a={name:"commands/command-sync-environments.md"};function r(o,e,d,c,m,h){return s(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="central-command-sync-environments" tabindex="-1">central command sync-environments <a class="header-anchor" href="#central-command-sync-environments" aria-label="Permalink to &quot;central command sync-environments&quot;">​</a></h1><p>Write the CustomerEnvironment record for each config named by --slug, from infra&#39;s registry joined to customerconfigs. Only the named configs are considered.</p><p>Each registry entry (Customers/&lt;prefix&gt;/) names its config (config_slug, else customer_prefix); the config&#39;s platformClientId is the environment id. Its customer_id is a roster slug: Customers/_command_ids.yaml gives the Command customer id and Customers/_customers.yaml its name. The document takes that owner, its name from full_customer_name, its intended use from intended_use, adminAppAudience from the config, and Source = Infra.</p><p>--command-tier says which Command database this is (prod or dev); --config must be that tier&#39;s centralconfig-&lt;tier&gt;.json, or nothing runs. An entry is written only when its github_environment names the same tier (Production = prod, Development = dev); one with no github_environment is skipped.</p><p>A roster customer missing from THIS Command database is skipped, unless --create-customers is given: then it is created under infra&#39;s id with its roster name and nothing else, and its records are written after it. Never: an existing customer is edited, a deleted customer&#39;s id is re-created, or a document whose Source is not Infra is written (refused).</p><p>A config named by --slug that has a tombstone (Customers/_retired/&lt;prefix&gt;.json) has its Infra document soft-deleted, found by the tombstone&#39;s platform_client_id.</p><p>Reported, never written: a named config with no registry entry or no file, entries with no customer_id (each with today&#39;s owner by record or client id, as a hint), an environment id two entries share, other customers still claiming an environment, an existing customer whose name differs from the roster, other customers carrying a roster name, Infra documents no entry names, and retired environments not named.</p><p>Writes go one at a time, each re-planned from fresh customers and records first; the run ends with a re-plan that should find zero writes. Any skipped or refused entry makes the run exit 1. Connects as the current Azure credential.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>central command sync-environments [options]</span></span></code></pre></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th><th>Required</th></tr></thead><tbody><tr><td><code>--config &lt;FileInfo&gt;</code></td><td>The platform config (customerconfigs AppSettings/centralconfig-{env}.json).</td><td>Yes</td></tr><tr><td><code>--registry &lt;DirectoryInfo&gt;</code></td><td>Infra&#39;s registry directory (central-infrastructure/Customers).</td><td>Yes</td></tr><tr><td><code>--configs &lt;DirectoryInfo&gt;</code></td><td>The customer config directory (customerconfigs/AppSettings).</td><td>Yes</td></tr><tr><td><code>--slug &lt;String[]&gt;</code></td><td>Config slugs to convert (customerconfigs file names without .json). Repeat, or separate with commas.</td><td>Yes</td></tr><tr><td><code>--apply</code></td><td>Make the planned writes. Without it, nothing is written and the plan is printed.</td><td>No</td></tr><tr><td><code>--command-tier &lt;String&gt;</code></td><td>prod or dev: the Command database --config must be. Entries whose github_environment names the other tier are skipped.</td><td>Yes</td></tr><tr><td><code>--create-customers</code></td><td>Create a roster customer missing from this Command database, under infra&#39;s id. Without it, its entries are skipped.</td><td>No</td></tr></tbody></table><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">central</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> command</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync-environments</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../customerconfigs/AppSettings/centralconfig-prod.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../central-infrastructure/Customers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --configs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../customerconfigs/AppSettings</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --slug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-prod,acme-test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --command-tier</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --create-customers</span></span></code></pre></div>`,14)])])}const g=t(a,[["render",r]]);export{p as __pageData,g as default};
